require_once __DIR__ . '/../Database.php';
require_once __DIR__ . '/../Response.php';
require_once __DIR__ . '/../Utils/Decimal.php';
require_once __DIR__ . '/../SystemLog.php';
require_once __DIR__ . '/CashVaultController.php';
require_once __DIR__ . '/OrdersController.php';
require_once __DIR__ . '/../Utils/EntityVersion.php';

use App\Utils\EntityVersion;

class CustomServicesController
{
    private function getCurrentUserId(): int
    {
        if (empty($_SESSION['user_id'])) {
            Response::json(['error' => 'Unauthorized'], 401);
            exit;
        }
        return (int)$_SESSION['user_id'];
    }

    /** GET /api/custom-services - List all service orders with pipeline status */
    public function index(): void
    {
        $db = Database::getConnection();
        
        $sql = "SELECT o.*, c.name AS customer_name, c.phone AS customer_phone, u.username AS technician_name, u.department AS technician_role 
                FROM orders o 
                LEFT JOIN customers c ON o.customer_id = c.id 
                LEFT JOIN users u ON o.owner_user_id = u.id 
                WHERE o.custom_sale = 1 AND o.deleted_at IS NULL 
                ORDER BY o.id DESC LIMIT 100";
        $services = $db->query($sql)->fetchAll();

        // Calculate 4 Bento KPIs
        $activeCount = 0;
        $inProgressCount = 0;
        $readyCount = 0;
        $deliveredCount = 0;
        $totalServicesProfit = '0';

        foreach ($services as &$s) {
            $st = $s['status'];
            if ($st === 'pending' || $st === 'received' || $st === 'diagnosing') {
                $activeCount++;
            } elseif ($st === 'in_progress' || $st === 'waiting_parts') {
                $inProgressCount++;
            } elseif ($st === 'ready') {
                $readyCount++;
            } elseif ($st === 'completed' || $st === 'delivered') {
                $deliveredCount++;
            }
            if ($st === 'completed' || $st === 'delivered' || $st === 'paid') {
                $totalServicesProfit = Decimal::add($totalServicesProfit, (string)$s['profit']);
            }

            // Zero-overfetching: strip heavy fileData Base64 strings from custom_checklist in list view
            if (!empty($s['custom_checklist'])) {
                $decoded = json_decode($s['custom_checklist'], true);
                if (is_array($decoded)) {
                    foreach ($decoded as &$item) {
                        if (isset($item['attachments']) && is_array($item['attachments'])) {
                            foreach ($item['attachments'] as &$att) {
                                if (isset($att['fileData'])) {
                                    unset($att['fileData']);
                                    $att['hasData'] = true;
                                }
                            }
                        }
                        if (isset($item['fileData'])) {
                            unset($item['fileData']);
                            $item['hasData'] = true;
                        }
                    }
                    $s['custom_checklist'] = json_encode($decoded);
                }
            }
        }
        unset($s);

        Response::json([
            'services' => $services,
            'kpis' => [
                'active_jobs'     => $activeCount,
                'in_progress'     => $inProgressCount,
                'ready_pickup'    => $readyCount,
                'delivered_today' => $deliveredCount,
                'services_profit' => $totalServicesProfit
            ]
        ]);
    }

    /** POST /api/custom-services - Fast New Service Job Intake */
    public function store(array $data): void
    {
        $db = Database::getConnection();

        $serviceName = trim((string)($data['service_name'] ?? ''));
        if ($serviceName === '') {
            Response::json(['error' => 'Service name is required'], 400);
            return;
        }

        $serviceDesc = trim((string)($data['service_description'] ?? ''));
        $customerNote = trim((string)($data['customer_note'] ?? $data['note'] ?? ''));
        $customerId = !empty($data['customer_id']) ? (int)$data['customer_id'] : 1; // Default to walk-in
        $creatorUserId = $this->getCurrentUserId();
        $techId = !empty($data['owner_user_id']) ? (int)$data['owner_user_id'] : $creatorUserId;
        if ($techId > 0) {
            $uCheck = $db->prepare('SELECT id FROM users WHERE id = :id');
            $uCheck->execute(['id' => $techId]);
            if (!$uCheck->fetchColumn()) {
                $techId = $creatorUserId;
            }
        }
        $totalPriceRaw = trim((string)($data['total_price'] ?? $data['total'] ?? '0'));
        $totalPrice = (is_numeric($totalPriceRaw) && Decimal::comp($totalPriceRaw, '0') >= 0) ? Decimal::truncate($totalPriceRaw, 16) : '0';

        $depositPaidRaw = trim((string)($data['deposit_paid'] ?? $data['amount_paid'] ?? '0'));
        $depositPaid = (is_numeric($depositPaidRaw) && Decimal::comp($depositPaidRaw, '0') > 0) ? Decimal::truncate($depositPaidRaw, 16) : '0';

        $manualCostRaw = trim((string)($data['manual_cost'] ?? '0'));
        $manualCost = (is_numeric($manualCostRaw) && Decimal::comp($manualCostRaw, '0') > 0) ? Decimal::truncate($manualCostRaw, 16) : '0';

        $partsCost = '0';
        $partsItems = (!empty($data['parts']) && is_array($data['parts'])) ? $data['parts'] : ((!empty($data['items']) && is_array($data['items'])) ? $data['items'] : []);
        foreach ($partsItems as $p) {
            $pQty = (string)($p['quantity'] ?? '1');
            $pCost = (string)($p['cost'] ?? '0');
            $partsCost = Decimal::add($partsCost, Decimal::mul($pQty, $pCost));
        }

        $totalCost = Decimal::add($manualCost, $partsCost);
        $profit = Decimal::sub($totalPrice, $totalCost);
        $status = !empty($data['status']) ? $data['status'] : 'received';

