        $customChecklist = !empty($data['custom_checklist']) ? (is_string($data['custom_checklist']) ? $data['custom_checklist'] : json_encode($data['custom_checklist'])) : null;
        $rawChecklist = !empty($data['custom_checklist']) ? (is_array($data['custom_checklist']) ? $data['custom_checklist'] : json_decode((string)$data['custom_checklist'], true)) : [];
        $deviceModel = !empty($data['device_model']) ? trim((string)$data['device_model']) : null;
        $deviceImei = !empty($data['device_imei']) ? trim((string)$data['device_imei']) : null;
        $devicePasscode = !empty($data['device_passcode']) ? trim((string)$data['device_passcode']) : null;
        $deviceCondition = !empty($data['device_condition']) ? trim((string)$data['device_condition']) : null;
        $deviceCustodyStatus = !empty($data['device_custody_status']) ? trim((string)$data['device_custody_status']) : 'on_me';
        $diagMatrix = isset($data['diagnostic_matrix']) ? (is_string($data['diagnostic_matrix']) ? $data['diagnostic_matrix'] : json_encode($data['diagnostic_matrix'])) : null;
        $handoverQcMatrix = isset($data['handover_qc_matrix']) ? (is_string($data['handover_qc_matrix']) ? $data['handover_qc_matrix'] : json_encode($data['handover_qc_matrix'])) : null;
        $warrantySeal = !empty($data['warranty_seal']) ? trim((string)$data['warranty_seal']) : null;
        $warrantyPeriod = !empty($data['warranty_period']) ? trim((string)$data['warranty_period']) : null;
        $warrantyExpiryDate = !empty($data['warranty_expiry_date']) ? (string)$data['warranty_expiry_date'] : null;
        $manualCostsData = !empty($data['manual_costs_data']) ? (is_string($data['manual_costs_data']) ? $data['manual_costs_data'] : json_encode($data['manual_costs_data'])) : null;
        $serviceOwnersData = !empty($data['service_owners_data']) ? (is_string($data['service_owners_data']) ? $data['service_owners_data'] : json_encode($data['service_owners_data'])) : null;
        $providerName = trim((string)($data['provider_name'] ?? ''));

        // Multi-Layer Consensus Detection (including Designated Owner != Creator)
        $hasExternalPartners = ($techId !== $creatorUserId);

        // Layer 1: Product Lots — check if any part has cost_owner_id != creatorUserId or techId
        foreach ($partsItems as $itm) {
            $cOwner = !empty($itm['cost_owner_id']) ? (int)$itm['cost_owner_id'] : null;
            if (!$cOwner && !empty($itm['purchase_id'])) {
                $pStmt = $db->prepare('SELECT owner_user_id FROM purchases WHERE id = :id');
                $pStmt->execute(['id' => $itm['purchase_id']]);
                $pRow = $pStmt->fetch();
                if ($pRow && !empty($pRow['owner_user_id'])) {
                    $cOwner = (int)$pRow['owner_user_id'];
                }
            }
            if ($cOwner && ($cOwner !== $techId || $cOwner !== $creatorUserId)) {
                $hasExternalPartners = true;
                break;
            }
        }

        // Layer 2: Manual Outlays
        if (!$hasExternalPartners && $manualCostsData) {
            $outlaysArr = json_decode($manualCostsData, true);
            if (is_array($outlaysArr)) {
