                    $pBy = !empty($mc['paid_by_user_id']) ? (int)$mc['paid_by_user_id'] : (!empty($mc['payer_user_id']) ? (int)$mc['payer_user_id'] : null);
                    if ($pBy && ($pBy !== $techId || $pBy !== $creatorUserId) && Decimal::comp((string)($mc['amount'] ?? '0'), '0') > 0) {
                        $hasExternalPartners = true;
                        break;
                    }
                }
            }
