                    :profit_split_type, :product_owner_share_pct, :product_owner_profit, :service_owner_profit
                )');
                $itemStmt->execute([
                    'order_id' => $orderId,
                    'product_id' => $itm['product_id'] ?? null,
                    'purchase_id' => $itm['purchase_id'] ?? null,
                    'name' => $itm['name'] ?? '',
                    'price' => (string)($itm['price'] ?? '0'),
                    'quantity' => (string)($itm['quantity'] ?? '1'),
                    'cost' => (string)($itm['cost'] ?? '0'),
                    'owner_user_id' => isset($itm['owner_user_id']) ? (int)$itm['owner_user_id'] : (isset($itm['cost_owner_id']) ? (int)$itm['cost_owner_id'] : $techId),
                    'cost_owner_id' => isset($itm['cost_owner_id']) ? (int)$itm['cost_owner_id'] : null,
                    'profit_split_type' => $itm['profit_split_type'] ?? 'none',
                    'product_owner_share_pct' => (string)($itm['product_owner_share_pct'] ?? '0'),
                    'product_owner_profit' => (string)($itm['product_owner_profit'] ?? '0'),
                    'service_owner_profit' => (string)($itm['service_owner_profit'] ?? '0')
                ]);
            }

