            if (!empty($partsItems)) {
                if ($status === 'completed' || $status === 'pending_money') {
                    $invErr = OrdersController::deductInventory($db, $partsItems);
                } else {
                    $invErr = OrdersController::reserveInventory($db, $partsItems);
                }
