    }

    /** PUT /api/custom-services/{id}/stage - Progress Service Job Stage */
    public function updateStage(string $id, array $data): void
    {
        $db = Database::getConnection();

        $newStage = trim((string)($data['stage'] ?? $data['status'] ?? ''));
        $validStages = ['received', 'diagnosing', 'in_progress', 'waiting_parts', 'ready', 'delivered', 'cancelled'];
        if (!in_array($newStage, $validStages, true)) {
            Response::json(['error' => 'Invalid service stage'], 400);
            return;
        }

        $db->beginTransaction();
        try {
            $stmt = $db->prepare("SELECT * FROM orders WHERE id = :id AND custom_sale = 1 FOR UPDATE");
            $stmt->execute(['id' => $id]);
            $order = $stmt->fetch();
            if (!$order) {
                $db->rollBack();
                Response::json(['error' => 'Service order not found'], 404);
                return;
            }

            $userId = $this->getCurrentUserId();
            $isAdmin = !empty($_SESSION['is_admin']) || (isset($_SESSION['role']) && ($_SESSION['role'] === 'admin' || $_SESSION['role'] === 'super_admin'));
            $isOwner = ((int)$order['owner_user_id'] === $userId);
            $isCreator = ((int)($order['created_by'] ?? 0) === $userId);
            $isPhase2 = !empty($order['is_locked_for_edit']) || (($order['agreement_status'] ?? '') === 'all_accepted');

            if ($newStage === 'cancelled' && $isPhase2) {
                $db->rollBack();
                Response::json(['error' => 'Custom services in Phase 2 cannot be cancelled directly. Please use the Return Order workflow.'], 422);
                return;
            }

            if ($isPhase2) {
                $mentionedUsers = OrdersController::getOrderMentionedUserIds($db, (int)$id, $order);
                $isParticipant = in_array($userId, $mentionedUsers, true);
                if (!$isOwner && !$isCreator && !$isParticipant && !$isAdmin) {
                    $db->rollBack();
                    Response::json(['error' => 'Only mentioned participants or admin can update the service stage in Phase 2'], 403);
                    return;
                }
            } else {
                if (!$isOwner && !$isCreator && !$isAdmin) {
                    $db->rollBack();
                    Response::json(['error' => 'Only the service owner, creator, or admin can update the stage during Phase 1 agreement'], 403);
                    return;
                }
            }

            // Check active partner settlements for pending or refused status
            $psCheck = $db->prepare("
                SELECT acceptance_status, status 
                FROM partner_settlements 
                WHERE related_entity_type = 'orders' 
                  AND related_entity_id = :oid 
                  AND status != 'cancelled' 
                  AND settlement_type != 'order_return_clawback'
            ");
            $psCheck->execute(['oid' => (int)$id]);
            $activeSettlements = $psCheck->fetchAll(PDO::FETCH_ASSOC);
            $hasPendingPs = false;
            $hasRefusedPs = false;
            foreach ($activeSettlements as $as) {
                if (($as['acceptance_status'] ?? '') === 'refused' || ($as['status'] ?? '') === 'refused') {
                    $hasRefusedPs = true;
                } elseif (($as['acceptance_status'] ?? 'pending') === 'pending') {
                    $hasPendingPs = true;
                }
            }

            if ($isPhase2) {
                // In Phase 2, intermediate stages (received, diagnosing, in_progress, waiting_parts, ready) are 100% unlocked;
                // ONLY 'delivered' (completion) is blocked if any Phase 2 partner is still pending or refused!
                if ($newStage === 'delivered' && ($hasPendingPs || $hasRefusedPs)) {
                    $db->rollBack();
                    Response::json([
                        'error' => 'Cannot mark service as delivered/completed: A Phase 2 partner has not yet accepted their statement (or has refused). Please wait for their acceptance or remove the unaccepted partner first.',
                        'agreement_status' => $order['agreement_status'],
                        'has_pending_partner' => $hasPendingPs,
                        'has_refused_partner' => $hasRefusedPs
                    ], 422);
                    return;
                }
            } else {
                // In Phase 1, progressing stages require all participants to have accepted first
                if (in_array($newStage, ['diagnosing', 'in_progress', 'waiting_parts', 'ready', 'delivered'], true) && (($order['agreement_status'] ?? '') !== 'all_accepted' || $hasPendingPs || $hasRefusedPs)) {
                    $db->rollBack();
                    Response::json([
                        'error' => 'Cannot start processing or deliver service: All participants must accept the Phase 1 agreement first.',
                        'agreement_status' => $order['agreement_status'],
                        'required' => 'all_accepted'
                    ], 422);
                    return;
                }
            }

            // Ensure payment demands are active for all unpaid manual costs in Phase 2
            if ($newStage === 'in_progress' && !empty($order['manual_costs_data'])) {
                $db->prepare("
                    UPDATE partner_settlements 
                    SET payment_demand_status = 'awaiting_payment', payment_demand_at = COALESCE(payment_demand_at, NOW())
                    WHERE related_entity_type = 'orders' 
                      AND related_entity_id = :oid 
                      AND settlement_type IN ('manual_cost_recovery', 'manual_cost_markup')
                      AND status != 'cancelled'
                      AND (payment_demand_status IS NULL OR payment_demand_status = 'none')
                ")->execute(['oid' => $id]);
            }

            $targetStatus = ($newStage === 'delivered') ? 'completed' : $newStage;
            $updFields = ["status = :st"];
            $params = ['st' => $targetStatus, 'id' => $id];

            // If delivered, mark completed, deduct inventory parts, and collect remaining balance if not paid
            if ($newStage === 'delivered') {
                // Fetch order items (service parts)
                $stmtItems = $db->prepare('SELECT product_id, purchase_id, quantity, cost, price FROM order_items WHERE order_id = :id');
                $stmtItems->execute(['id' => $id]);
                $items = $stmtItems->fetchAll(PDO::FETCH_ASSOC);

                if ($order['status'] !== 'completed' && $order['status'] !== 'delivered') {
                    // Release pending reservation first, then deduct actual inventory
                    OrdersController::releaseInventory($db, $items);
                    $deductErr = OrdersController::deductInventory($db, $items);
                    if ($deductErr) {
                        $db->rollBack();
                        Response::json(['error' => "Cannot deliver service: {$deductErr}"], 400);
                        return;
                    }
                }

                $updFields[] = "completed_at = NOW()";
                $updFields[] = "completed_by = :cb";
                $params['cb'] = $this->getCurrentUserId();

                $total = (string)$order['total'];
                $alreadyPaid = (string)$order['amount_paid'];
                $remainingBalance = Decimal::sub($total, $alreadyPaid);

                if (Decimal::comp($remainingBalance, '0') > 0) {
                    $updFields[] = "amount_paid = :ap";
                    $updFields[] = "paid_at = NOW()";
                    $updFields[] = "paid_by = :pb";
                    $params['ap'] = $total;
                    $params['pb'] = $this->getCurrentUserId();

                    // Deposit remaining balance into Safe 2 (Services Safe) for service owner (custodian)
                    $ownerSafeId = !empty($order['owner_user_id']) ? (int)$order['owner_user_id'] : $this->getCurrentUserId();
                    $deliveringCashierId = $this->getCurrentUserId();
                    $deliveryNote = "Service Final Balance: {$order['service_name']}";
                    if ($deliveringCashierId !== $ownerSafeId) {
                        $uStmt = $db->prepare('SELECT username FROM users WHERE id = :id LIMIT 1');
                        $uStmt->execute(['id' => (int)$deliveringCashierId]);
                        $cashierUsername = $uStmt->fetchColumn() ?: "Cashier #{$deliveringCashierId}";
                        $deliveryNote .= " (Collected at counter by {$cashierUsername})";
                    }
                    CashVaultController::logFlow($db, 'service_final_payment', 'in', $remainingBalance, 'orders', (int)$id, $deliveryNote, $ownerSafeId);
                }
            } elseif ($newStage === 'cancelled') {
                // Fetch order items (service parts)
                $stmtItems = $db->prepare('SELECT product_id, purchase_id, quantity, cost, price FROM order_items WHERE order_id = :id');
                $stmtItems->execute(['id' => $id]);
                $items = $stmtItems->fetchAll(PDO::FETCH_ASSOC);

                // If previously completed/delivered, restore inventory with full recursive lineage support!
                if ($order['status'] === 'completed' || $order['status'] === 'delivered') {
                    OrdersController::restoreInventory($db, $items, 'absorb_master', $order['uid'] ?? null, (int)$id);
                } else {
                    // Otherwise, release reservation
                    OrdersController::releaseInventory($db, $items);
                }

                // Cash reversal for any collected deposit/payments from Safe 2
                $alreadyPaid = (string)($order['amount_paid'] ?? '0');
                if (Decimal::comp($alreadyPaid, '0') > 0) {
                    CashVaultController::logFlow(
                        $db,
                        'service_refund',
                        'out',
                        $alreadyPaid,
                        'orders',
                        (int)$id,
                        "Service Cancelled Refund: {$order['service_name']}",
                        (int)($order['owner_user_id'] ?? $this->getCurrentUserId())
                    );
                    $updFields[] = "amount_paid = 0";
                }

                // Cancel pending/disputed/refused partner settlements
                OrdersController::cancelPartnerSettlements($db, (int)$id, 'Service order cancelled');
            }

            // Optional warranty & QC handover updates
            if (!empty($data['warranty_seal'])) {
                $updFields[] = "warranty_seal = :wseal";
                $params['wseal'] = trim((string)$data['warranty_seal']);
            }
            if (!empty($data['warranty_period'])) {
                $updFields[] = "warranty_period = :wperiod";
                $params['wperiod'] = trim((string)$data['warranty_period']);
            }
            if (!empty($data['warranty_expiry_date'])) {
                $updFields[] = "warranty_expiry_date = :wexp";
                $params['wexp'] = (string)$data['warranty_expiry_date'];
            }
            if (isset($data['diagnostic_matrix'])) {
                $updFields[] = "diagnostic_matrix = :dmatrix";
                $params['dmatrix'] = is_string($data['diagnostic_matrix']) ? $data['diagnostic_matrix'] : json_encode($data['diagnostic_matrix']);
            }
            if (!empty($data['device_custody_status'])) {
                $updFields[] = "device_custody_status = :dcs";
                $params['dcs'] = trim((string)$data['device_custody_status']);
            }
            if (isset($data['handover_qc_matrix'])) {
                $updFields[] = "handover_qc_matrix = :hqc";
                $params['hqc'] = is_string($data['handover_qc_matrix']) ? $data['handover_qc_matrix'] : json_encode($data['handover_qc_matrix']);
            }

            $db->prepare("UPDATE orders SET " . implode(', ', $updFields) . " WHERE id = :id")->execute($params);

            if ($newStage === 'delivered') {
                OrdersController::generatePartnerSettlements($db, (int)$id, $order['uid'] ?? '', (int)($order['owner_user_id'] ?? $this->getCurrentUserId()));
            }

            // Record Order History Snapshot for stage change
            try {
                $snapshot = OrdersController::captureOrderSnapshot($db, (int)$id);
                if (!empty($snapshot['order'])) {
                    $snapshot['order']['status'] = $targetStatus;
                    $snapshot['status'] = $targetStatus;
                }
                OrdersController::recordOrderHistory(
                    $db,
                    (int)$id,
                    $userId,
                    'stage_changed',
                    [
                        'Stage' => ['from' => ucfirst($order['status']), 'to' => ucfirst($newStage)]
                    ],
                    "Progressed stage from {$order['status']} to {$newStage}",
                    $snapshot
                );
            } catch (\Throwable $th) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $th->getMessage());
        }

            $db->commit();

            EntityVersion::bump($db, 'orders', 'partner_settlements', 'cash_vault');

            SystemLog::write('custom_services', 'stage_updated', (int)$id, $order['service_name'], json_encode([
                'order_id'  => (int)$id,
                'old_stage' => $order['status'],
                'new_stage' => $newStage
            ]));

            Response::json(['ok' => true, 'new_stage' => $newStage]);
        } catch (\Throwable $e) {
            if ($db->inTransaction()) $db->rollBack();
            error_log("Failed to update service stage in " . __METHOD__ . ": " . $e->getMessage());
            Response::json(['error' => 'Failed to update service stage. Please check server logs.'], 500);
        }
    }

    /** GET /api/custom-services/{id}/checklist - Lazy-load full checklist with attachments */
    public function getChecklist(string $id): void
    {
        $db = Database::getConnection();
        $stmt = $db->prepare("SELECT custom_checklist FROM orders WHERE id = :id AND custom_sale = 1");
        $stmt->execute(['id' => $id]);
        $order = $stmt->fetch();
        if (!$order) {
            Response::json(['error' => 'Service not found'], 404);
            return;
        }
        $checklist = !empty($order['custom_checklist']) ? json_decode($order['custom_checklist'], true) : [];
        Response::json(['checklist' => $checklist]);
    }

    public function resubmitAfterRefusal(string $id): void
    {
        $db = Database::getConnection();
        try {
            $db->beginTransaction();

            $stmt = $db->prepare("SELECT * FROM orders WHERE id = :id AND custom_sale = 1 FOR UPDATE");
            $stmt->execute(['id' => $id]);
            $order = $stmt->fetch();

            if (!$order || !(int)$order['has_refusal']) {
                if ($db->inTransaction()) $db->rollBack();
                Response::json(['error' => 'Service not found or has no active refusal'], 400);
                return;
            }

            $currentUserId = $this->getCurrentUserId();
            $isAdmin = !empty($_SESSION['is_admin']) || (isset($_SESSION['role']) && ($_SESSION['role'] === 'admin' || $_SESSION['role'] === 'super_admin'));
            $isOwner = ($currentUserId === (int)$order['owner_user_id']);
            $isCreator = ($currentUserId === (int)($order['created_by'] ?? 0));
            if (!$isOwner && !$isCreator && !$isAdmin) {
                if ($db->inTransaction()) $db->rollBack();
                Response::json(['error' => 'Unauthorized. Only the owner or creator can resubmit.'], 403);
                return;
            }

            $newVersion = (int)$order['agreement_version'] + 1;
            OrdersController::cancelPartnerSettlements($db, (int)$id, 'Service re-edited after refusal v' . $newVersion);

            $db->prepare("UPDATE orders SET agreement_status = 'pending', has_refusal = 0, is_locked_for_edit = 0, agreement_version = :v WHERE id = :id")
               ->execute(['v' => $newVersion, 'id' => $id]);

            OrdersController::generatePartnerSettlements($db, (int)$id, $order['uid'] ?? '', (int)$order['owner_user_id']);
            OrdersController::syncOrderAgreementStatus($db, (int)$id);

            $db->prepare("INSERT INTO order_history (order_id, edited_by, action, changes, created_at) VALUES (:oid, :uid, :action, :changes, NOW())")
               ->execute([
                   'oid' => $id,
                   'uid' => $currentUserId,
                   'action' => 'resubmitted_after_refusal',
                   'changes' => json_encode(['old_version' => (int)$order['agreement_version'], 'new_version' => $newVersion])
               ]);

            $db->commit();

            EntityVersion::bump($db, 'orders', 'partner_settlements', 'cash_vault');

            $serviceName = $order['service_name'] ?? 'Custom Service';
            SystemLog::write('custom_services', 'resubmitted', $id, $serviceName, json_encode([
                'order_id' => $id,
                'order_uid' => $order['uid'] ?? '',
                'action' => 'resubmitted_after_refusal',
                'new_version' => $newVersion
            ]), $currentUserId);

            Response::json(['ok' => true, 'new_version' => $newVersion]);
        } catch (\Throwable $e) {
            if ($db->inTransaction()) $db->rollBack();
            error_log("Failed to resubmit service in " . __METHOD__ . ": " . $e->getMessage());
            Response::json(['error' => 'Failed to resubmit service. Please check server logs.'], 500);
        }
    }
}

